package tr.gunplan.app;
import android.content.Context;import org.json.*;import java.util.*;import java.time.*;
final class Backup{
 static String key(JSONObject t){return t.optString("title")+"|"+t.optString("note")+"|"+t.optString("date")+"|"+t.optString("time")+"|"+t.optString("repeat")+"|"+t.optInt("weekMask")+"|"+t.optInt("monthDay")+"|"+t.optString("category")+"|"+("monthly".equals(t.optString("repeat"))&&!t.optBoolean("monthEnd",false)&&t.optBoolean("nextWeekday",false))+"|"+t.optBoolean("monthEnd",false)+"|"+(t.optBoolean("monthEnd",false)&&t.optBoolean("previousWeekday",false));}
 static synchronized int merge(Context c,String text)throws Exception{synchronized(TaskStore.class){JSONObject input=new JSONObject(text);if(input.optInt("schema")!=1)throw new Exception("Bu dosya Gün Plan yedeği değil.");JSONArray source=input.getJSONArray("tasks");if(source.length()>1000)throw new Exception("Yedekte çok fazla görev var.");JSONObject s=TaskStore.read(c);JSONArray tasks=s.getJSONArray("tasks");Set<String> seen=new HashSet<>();for(int i=0;i<tasks.length();i++)seen.add(key(tasks.getJSONObject(i)));int count=0,nextId=s.getInt("nextId");long now=System.currentTimeMillis();
  for(int i=0;i<source.length();i++){JSONObject raw=source.getJSONObject(i),t=TaskStore.clean(raw);if(!seen.add(key(t)))continue;long due=TaskStore.next(t,now-1);boolean past=due<0;if(past)due=java.time.LocalDate.parse(t.getString("date")).atTime(java.time.LocalTime.parse(t.getString("time"))).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();t.put("id",nextId++).put("due",due).put("enabled",!past&&raw.optBoolean("enabled",true)).put("completed",past||raw.optBoolean("completed")).put("notifiedAt",0).put("createdAt",now);tasks.put(t);count++;}
  if(tasks.length()>1000)throw new Exception("Toplam görev sayısı 1000'i geçemez.");s.put("nextId",nextId);
  JSONArray history=s.getJSONArray("history"),old=input.optJSONArray("history");Set<String> histories=new HashSet<>();for(int i=0;i<history.length();i++)histories.add(history.getJSONObject(i).optString("title")+"|"+history.getJSONObject(i).optLong("at"));if(old!=null){if(old.length()>300)throw new Exception("Geçmiş kaydı sınırı aşıldı.");for(int i=0;i<old.length();i++){JSONObject h=old.getJSONObject(i);String title=h.getString("title");long at=h.getLong("at");if(title.isEmpty()||title.length()>120||at<=0)throw new Exception("Geçmiş kayıt biçimi geçersiz.");if(histories.add(title+"|"+at))history.put(new JSONObject().put("title",title).put("at",at).put("category",h.optString("category","Kişisel")).put("occurrence",h.optLong("occurrence")).put("taskId",0));}}java.util.List<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<history.length();i++)sorted.add(history.getJSONObject(i));sorted.sort(java.util.Comparator.comparingLong(h->h.optLong("at")));JSONArray retained=new JSONArray();for(int i=Math.max(0,sorted.size()-300);i<sorted.size();i++)retained.put(sorted.get(i));s.put("history",retained);TaskStore.write(c,s);return count;}}
}
